"""Run one explicitly supervised root build and preserve its full output."""
import argparse
import datetime
import hashlib
import json
import os
from pathlib import Path
import subprocess

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
JDK = Path('/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8')
MVN = Path('/workspace/scratch/d0a0e51b9386/toolchain/maven-mvnd-1.0.6-linux-amd64/mvn/bin/mvn')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('attempt')
    parser.add_argument('--online', action='store_true')
    parser.add_argument('--serial', action='store_true')
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted or Path(args.attempt).name != args.attempt:
        raise ValueError('A simple new attempt and exclusive Java slot are required')
    path = HERE / args.attempt
    path.mkdir(exist_ok=False)
    argv = [str(MVN), '-B', '-ntp', '-Dmaven.compiler.showWarnings=false']
    if not args.serial:
        argv += ['-T', '1C']
    if not args.online:
        argv += ['-o']
    argv += ['-Dmaven.repo.local=.m2_repo', '-Pquick', 'clean', 'install']
    env = os.environ.copy()
    env['JAVA_HOME'] = str(JDK)
    env['PATH'] = str(JDK / 'bin') + os.pathsep + env.get('PATH', '')
    record = {'argv': argv, 'cwd': str(ROOT), 'started': datetime.datetime.now(datetime.timezone.utc).isoformat()}
    (path / 'command.json').write_text(json.dumps(record, indent=2) + '\n')
    with (path / 'maven-build.log').open('xb') as log, (ROOT / 'maven-build.log').open('wb') as root_log:
        process = subprocess.Popen(argv, cwd=ROOT, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        summary = False
        for line in process.stdout:
            log.write(line)
            root_log.write(line)
            text = line.decode(errors='replace').rstrip()
            summary |= 'Reactor Summary' in text
            if ('[ERROR]' in text or summary) and '[WARNING]' not in text:
                print(text, flush=True)
        code = process.wait()
    record.update(exitCode=code, finished=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  logSha256=hashlib.sha256((path / 'maven-build.log').read_bytes()).hexdigest())
    (path / 'command.json').write_text(json.dumps(record, indent=2) + '\n')
    print(json.dumps({'exitCode': code, 'receipt': str(path / 'command.json')}), flush=True)
    raise SystemExit(code)


if __name__ == '__main__':
    main()
